CREATE TABLE rfpilot.proposal_draft_runs(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES rfpilot.organizations(id),proposal_reference_id uuid NOT NULL REFERENCES rfpilot.proposal_references(id),job_id uuid NOT NULL UNIQUE REFERENCES rfpilot.ai_jobs(id),actor_external_user_id varchar(24) NOT NULL CHECK(actor_external_user_id~'^[0-9a-f]{24}$'),status text NOT NULL CHECK(status IN('queued','running','succeeded','conflict','failed')),expected_proposal_version integer NOT NULL CHECK(expected_proposal_version>0),provider text NOT NULL DEFAULT 'mock' CHECK(provider='mock'),model text NOT NULL DEFAULT 'deterministic-v1' CHECK(model='deterministic-v1'),schema_version text NOT NULL DEFAULT 'proposal-draft.v1',fixture text NOT NULL CHECK(fixture='synthetic-proposal-draft'),output_checksum char(64),section_count smallint NOT NULL DEFAULT 0 CHECK(section_count BETWEEN 0 AND 10),paragraph_count smallint NOT NULL DEFAULT 0 CHECK(paragraph_count BETWEEN 0 AND 30),citation_count smallint NOT NULL DEFAULT 0 CHECK(citation_count BETWEEN 0 AND 100),gap_count smallint NOT NULL DEFAULT 0,safe_error_code text,idempotency_key text NOT NULL,correlation_id uuid NOT NULL,retention_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(organization_id,idempotency_key));
CREATE TABLE rfpilot.proposal_draft_sections(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES rfpilot.organizations(id),run_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_runs(id),ordinal smallint NOT NULL,key text NOT NULL CHECK(key IN('event_overview','objectives_audience','format_experience','venue_schedule','production_scope','known_requirements','information_gaps')),heading text NOT NULL CHECK(length(heading)<=200),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,ordinal));
CREATE TABLE rfpilot.proposal_draft_paragraphs(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES rfpilot.organizations(id),run_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_runs(id),section_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_sections(id),ordinal smallint NOT NULL,text text NOT NULL CHECK(length(text) BETWEEN 1 AND 4000),text_checksum char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(section_id,ordinal));
CREATE TABLE rfpilot.proposal_draft_citations(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES rfpilot.organizations(id),run_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_runs(id),paragraph_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_paragraphs(id),canonical_path text NOT NULL CHECK(canonical_path~'^/content/'),value_checksum char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(paragraph_id,canonical_path));
CREATE TABLE rfpilot.proposal_draft_gaps(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES rfpilot.organizations(id),run_id uuid NOT NULL REFERENCES rfpilot.proposal_draft_runs(id),ordinal smallint NOT NULL,code text NOT NULL,paths text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,ordinal));
ALTER TABLE rfpilot.proposal_draft_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_runs FORCE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_sections ENABLE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_sections FORCE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_paragraphs ENABLE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_paragraphs FORCE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_citations ENABLE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_citations FORCE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_gaps ENABLE ROW LEVEL SECURITY;ALTER TABLE rfpilot.proposal_draft_gaps FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_proposal_draft_runs ON rfpilot.proposal_draft_runs USING(organization_id=rfpilot.current_organization_id()) WITH CHECK(organization_id=rfpilot.current_organization_id());CREATE POLICY tenant_proposal_draft_sections ON rfpilot.proposal_draft_sections USING(organization_id=rfpilot.current_organization_id()) WITH CHECK(organization_id=rfpilot.current_organization_id());CREATE POLICY tenant_proposal_draft_paragraphs ON rfpilot.proposal_draft_paragraphs USING(organization_id=rfpilot.current_organization_id()) WITH CHECK(organization_id=rfpilot.current_organization_id());CREATE POLICY tenant_proposal_draft_citations ON rfpilot.proposal_draft_citations USING(organization_id=rfpilot.current_organization_id()) WITH CHECK(organization_id=rfpilot.current_organization_id());CREATE POLICY tenant_proposal_draft_gaps ON rfpilot.proposal_draft_gaps USING(organization_id=rfpilot.current_organization_id()) WITH CHECK(organization_id=rfpilot.current_organization_id());
CREATE FUNCTION rfpilot.reject_proposal_draft_result_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'proposal draft results are immutable';END$$;CREATE TRIGGER draft_sections_immutable BEFORE UPDATE OR DELETE ON rfpilot.proposal_draft_sections FOR EACH ROW EXECUTE FUNCTION rfpilot.reject_proposal_draft_result_mutation();CREATE TRIGGER draft_paragraphs_immutable BEFORE UPDATE OR DELETE ON rfpilot.proposal_draft_paragraphs FOR EACH ROW EXECUTE FUNCTION rfpilot.reject_proposal_draft_result_mutation();CREATE TRIGGER draft_citations_immutable BEFORE UPDATE OR DELETE ON rfpilot.proposal_draft_citations FOR EACH ROW EXECUTE FUNCTION rfpilot.reject_proposal_draft_result_mutation();CREATE TRIGGER draft_gaps_immutable BEFORE UPDATE OR DELETE ON rfpilot.proposal_draft_gaps FOR EACH ROW EXECUTE FUNCTION rfpilot.reject_proposal_draft_result_mutation();
